def _positive_fraction(value, label: str) -> Fraction:
    try:
        parsed = Fraction(str(value))
    except (TypeError, ValueError, ZeroDivisionError) as exc:
        raise SpinoffTermsRequired(f"invalid {label}") from exc
    if parsed <= 0:
        raise SpinoffTermsRequired(f"invalid {label}")
    return parsed

_session.source:
def _session(value):
    if date.fromisoformat(value).isoformat() != value or len(value) != 10:
        raise ValueError("canonical ISO session required")
    return value
